PARTITION_COUNT = 4
ITEM_KEYS = ['alice', 'bob', 'carol', 'alice', 'alice', 'dave', 'erin', 'alice']

def partition_for(key):
    return sum(ord(c) for c in key) % PARTITION_COUNT

def partition_counts(keys):
    counts = [0] * PARTITION_COUNT
    for key in keys:
        counts[partition_for(key)] += 1
    return counts

counts = partition_counts(ITEM_KEYS)
for n, count in enumerate(counts):
    print(f'partition {n}: {count}')

for n, count in enumerate(counts):
    if count > len(ITEM_KEYS) / 2:
        print(f'hot partition: {n}')
